import React, { useState, useEffect, useMemo } from "react";
import {
  ResponsiveContainer,
  ScatterChart,
  Scatter,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
} from "recharts";

export default function SeedCatalog() {
  const [data, setData] = useState([]);
  const [search, setSearch] = useState("");
  const [marketFilter, setMarketFilter] = useState("all");
  const [selected, setSelected] = useState([]);
  const [xTrait, setXTrait] = useState("yield_kg_ha");
  const [yTrait, setYTrait] = useState("maturity_days");
  const [activeVariety, setActiveVariety] = useState(null);

  // Load data
  useEffect(() => {
    fetch("/seed-catalog/data/uog-varieties.json")
      .then((res) => res.json())
      .then((json) => setData(json));
  }, []);

  // Resistance score
  function resistanceScore(r) {
    if (!r) return "NA";
    const vals = Object.values(r).filter((v) => v && v !== "N/A");
    if (!vals.length) return "NA";
    const resistant = vals.filter((v) => v === "R").length;
    return ((resistant / vals.length) * 100).toFixed(0) + "%";
  }

  // Trait options
  const traitOptions = [
    { key: "yield_kg_ha", label: "Yield (kg/ha)" },
    { key: "maturity_days", label: "Maturity (days)" },
    { key: "seed_weight_g", label: "Seed weight (g)" },
    { key: "harvestability", label: "Harvestability" },
  ];

  // Market classes
  const marketClasses = useMemo(() => {
    const s = new Set(data.map((d) => d.marketClass).filter(Boolean));
    return ["all", ...Array.from(s)];
  }, [data]);

  // Safe filtering (cannot crash)
  const filtered = useMemo(() => {
    return data.filter(
      (d) =>
        (marketFilter === "all" || d.marketClass === marketFilter) &&
        ((d.name ?? "") + "")
          .toLowerCase()
          .includes(search.toLowerCase())
    );
  }, [data, search, marketFilter]);

  // Compare selection
  function toggleSelect(id) {
    setSelected((s) => {
      if (s.includes(id)) return s.filter((x) => x !== id);
      if (s.length >= 5) return s;
      return [...s, id];
    });
  }

  const compareRows = filtered.filter((d) =>
    selected.includes(d.id)
  );

  // Scatter data (only valid numbers)
  const scatterData = compareRows
    .filter(
      (d) =>
        typeof d[xTrait] === "number" &&
        typeof d[yTrait] === "number"
    )
    .map((d) => ({
      x: d[xTrait],
      y: d[yTrait],
      name: d.name,
    }));

  return (
    <div style={{ padding: 40 }}>
      <h1>University of Guelph Seed Catalog</h1>

      {/* Controls */}
      <div style={{ display: "flex", gap: 10, marginBottom: 20 }}>
        <input
          placeholder="Search variety..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />

        <select
          value={marketFilter}
          onChange={(e) => setMarketFilter(e.target.value)}
        >
          {marketClasses.map((m) => (
            <option key={m}>{m}</option>
          ))}
        </select>
      </div>

      {/* Cards */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fill, minmax(240px, 1fr))",
          gap: 20,
        }}
      >
        {filtered.map((v) => (
          <div
            key={v.id}
            onClick={() => setActiveVariety(v)}
            style={{
              border: "1px solid #ddd",
              borderRadius: 12,
              overflow: "hidden",
              boxShadow: "0 4px 10px rgba(0,0,0,0.08)",
              cursor: "pointer",
              transition: "0.2s",
              background: selected.includes(v.id)
                ? "#e8f4ff"
                : "white",
            }}
          >
            <img
              src={
                v.imageUrl ||
                `https://dummyimage.com/400x250/eee/333&text=${encodeURIComponent(
                  v.name
                )}`
              }
              style={{ width: "100%", height: 160, objectFit: "cover" }}
            />
            <div style={{ padding: 10 }}>
              <h3>{v.name}</h3>
              <p>{v.marketClass}</p>
              <p>Yield: {v.yield_kg_ha ?? "NA"}</p>
              <p>Maturity: {v.maturity_days ?? "NA"}</p>

              <label>
                <input
                  type="checkbox"
                  checked={selected.includes(v.id)}
                  onClick={(e) => e.stopPropagation()}
                  onChange={() => toggleSelect(v.id)}
                />
                Compare
              </label>
            </div>
          </div>
        ))}
      </div>

      {/* Scatter */}
      <h2 style={{ marginTop: 40 }}>Trait Comparison</h2>

      <div style={{ display: "flex", gap: 10 }}>
        X:
        <select onChange={(e) => setXTrait(e.target.value)}>
          {traitOptions.map((t) => (
            <option key={t.key} value={t.key}>
              {t.label}
            </option>
          ))}
        </select>

        Y:
        <select onChange={(e) => setYTrait(e.target.value)}>
          {traitOptions.map((t) => (
            <option key={t.key} value={t.key}>
              {t.label}
            </option>
          ))}
        </select>
      </div>

      {scatterData.length > 0 && (
        <ResponsiveContainer width="100%" height={350}>
          <ScatterChart>
            <CartesianGrid />
            <XAxis type="number" dataKey="x" />
            <YAxis type="number" dataKey="y" />
            <Tooltip />
            <Scatter data={scatterData} fill="#2b7cff" />
          </ScatterChart>
        </ResponsiveContainer>
      )}

      {/* Modal */}
      {activeVariety && (
        <div
          onClick={() => setActiveVariety(null)}
          style={{
            position: "fixed",
            inset: 0,
            background: "rgba(0,0,0,0.7)",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
          }}
        >
          <div
            onClick={(e) => e.stopPropagation()}
            style={{ background: "white", padding: 30, width: 600 }}
          >
            <h2>{activeVariety.name}</h2>
            <img
              src={
                activeVariety.imageUrl ||
                `https://dummyimage.com/600x350/eee/333&text=${encodeURIComponent(
                  activeVariety.name
                )}`
              }
              style={{ width: "100%", marginBottom: 20 }}
            />

            <ul>
              <li>Market class: {activeVariety.marketClass}</li>
              <li>Yield: {activeVariety.yield_kg_ha ?? "NA"}</li>
              <li>Maturity: {activeVariety.maturity_days ?? "NA"}</li>
              <li>Seed weight: {activeVariety.seed_weight_g ?? "NA"}</li>
              <li>Harvestability: {activeVariety.harvestability ?? "NA"}</li>
            </ul>

            <h4>Resistance</h4>
            <ul>
              {Object.entries(
                activeVariety.resistance || {}
              ).map(([k, v]) => (
                <li key={k}>
                  {k.replace(/_/g, " ")}: {v || "NA"}
                </li>
              ))}
            </ul>

            <p>
              Resistance score:{" "}
              {resistanceScore(activeVariety.resistance)}
            </p>

            <button onClick={() => setActiveVariety(null)}>
              Close
            </button>
          </div>
        </div>
      )}
    </div>
  );
}